func (n *statusNode) role() string {
    for k := range n.Metadata.Labels {
        if k == "node-role.kubernetes.io/master" {
            return "master"
        }
        if k == "node-role.kubernetes.io/worker" {
            return "worker"
        }
    }
    return "unknown"
}

